import numpy as np
import pytest

from poly import make_data, raw_cv_r2, fit_poly_coefficients, poly_cv_r2


@pytest.fixture(scope="module")
def data():
    return make_data()


def test_raw_features_poor_fit(data):
    X, y = data
    r2 = raw_cv_r2(X, y)
    assert r2 <= 0.75, f"raw CV R^2 {r2:.4f} unexpectedly high"


def test_polynomial_recovers_signal(data):
    X, y = data
    r2 = poly_cv_r2(X, y)
    assert r2 >= 0.995, f"poly CV R^2 {r2:.4f} too low"


def test_coefficient_recovery(data):
    X, y = data
    names, coef, _ = fit_poly_coefficients(X, y)
    expected = {"x0^2": 2.0, "x0 x1": -3.0, "x1": 1.0}
    for term, true_val in expected.items():
        learned = coef[term]
        err = abs(learned - true_val)
        assert err <= 0.05, (
            f"{term}: learned {learned:+.4f}, expected {true_val:+.4f}, |err|={err:.4f}"
        )

